#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int kthLargestValue(vector<vector<int>>& matrix, int k) {
        int m = matrix.size(), n = matrix[0].size();
        vector<vector<int>> val(m + 1, vector<int>(n + 1, 0));
        vector<int> values;
        values.reserve(m * n);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                val[r + 1][c + 1] = val[r][c + 1] ^ val[r + 1][c] ^ val[r][c] ^ matrix[r][c];
                values.push_back(val[r + 1][c + 1]);
            }
        }
        sort(values.rbegin(), values.rend());
        return values[k - 1];
    }
};

import java.util.Arrays;

class Solution {
    public int kthLargestValue(int[][] matrix, int k) {
        int m = matrix.length, n = matrix[0].length;
        int[][] val = new int[m + 1][n + 1];
        int[] values = new int[m * n];
        int idx = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                val[r + 1][c + 1] = val[r][c + 1] ^ val[r + 1][c] ^ val[r][c] ^ matrix[r][c];
                values[idx++] = val[r + 1][c + 1];
            }
        }
        Arrays.sort(values);
        return values[values.length - k];
    }
}

/**
 * @param {number[][]} matrix
 * @param {number} k
 * @return {number}
 */
var kthLargestValue = function(matrix, k) {
    const m = matrix.length, n = matrix[0].length;
    const val = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    const values = [];
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            val[r + 1][c + 1] = val[r][c + 1] ^ val[r + 1][c] ^ val[r][c] ^ matrix[r][c];
            values.push(val[r + 1][c + 1]);
        }
    }
    values.sort((a, b) => b - a);
    return values[k - 1];
};
